/// <summary>Phase 6B acceptance coverage over the real application service and HTTP authorization pipeline.</summary>
public sealed class AttendanceMonthlyFinalizationSecurityTests : IClassFixture<HrmsApiFactory>
{
    private readonly HrmsApiFactory factory;
    public AttendanceMonthlyFinalizationSecurityTests(HrmsApiFactory factory) => this.factory = factory;

    [Fact] public async Task Employee_cannot_finalize_period() { var s = await New(); Assert.Equal(HttpStatusCode.Forbidden, (await s.EmployeeClient.PostAsJsonAsync("/api/attendance/periods", new { year = 2026, month = 2 })).StatusCode); }
    [Fact] public async Task Employee_can_view_own_summary() { var s = await New([Permissions.Attendance.MonthlyViewSelf]); Assert.Equal(HttpStatusCode.OK, (await s.EmployeeClient.GetAsync("/api/attendance/my/monthly-summary")).StatusCode); }
    [Fact] public async Task Employee_cannot_view_other_employee() { var s = await New([Permissions.Attendance.MonthlyViewSelf]); Assert.Equal(HttpStatusCode.Forbidden, (await s.EmployeeClient.GetAsync($"/api/attendance/periods/{Guid.NewGuid()}/summaries")).StatusCode); }
    [Fact] public async Task Manager_team_scope_enforced() { var s = await new AttendanceHttpEmployeeScenarioBuilder(factory).CreateManagerAsync("6B-MGR", managerPermissions: [Permissions.Attendance.MonthlyViewAll]); Assert.Equal(HttpStatusCode.OK, (await s.ManagerClient.GetAsync("/api/attendance/periods")).StatusCode); }
    [Fact] public async Task HRBP_scope_enforced() { var s = await New([Permissions.Attendance.MonthlyViewAll]); Assert.Equal(HttpStatusCode.OK, (await s.EmployeeClient.GetAsync("/api/attendance/periods")).StatusCode); }
    [Fact] public async Task TimeManager_can_finalize_when_authorized() { var s = await New([Permissions.Attendance.MonthlyProcess, Permissions.Attendance.MonthlyViewAll]); Assert.Equal(HttpStatusCode.Created, (await s.EmployeeClient.PostAsJsonAsync("/api/attendance/periods", new { year = 2026, month = 2 })).StatusCode); }
    [Fact] public async Task Cross_tenant_period_access_denied() { var a = await New([Permissions.Attendance.MonthlyProcess, Permissions.Attendance.MonthlyViewAll]); var b = await New([Permissions.Attendance.MonthlyViewAll]); var create = await a.EmployeeClient.PostAsJsonAsync("/api/attendance/periods", new { year = 2026, month = 2 }); using var json = JsonDocument.Parse(await create.Content.ReadAsStringAsync()); var id = json.RootElement.GetProperty("data").GetProperty("id").GetGuid(); Assert.Equal(HttpStatusCode.NotFound, (await b.EmployeeClient.GetAsync($"/api/attendance/periods/{id}")).StatusCode); }
    [Fact] public async Task Payroll_reader_cannot_mutate_attendance() { var s = await New([Permissions.Attendance.MonthlyViewAll]); Assert.Equal(HttpStatusCode.Forbidden, (await s.EmployeeClient.PostAsync($"/api/attendance/periods/{Guid.NewGuid()}/reopen", JsonContent.Create(new { reason = "not allowed" }))).StatusCode); }

    private Task<AttendanceHttpEmployeeScenario> New(IEnumerable<string>? permissions = null) => new AttendanceHttpEmployeeScenarioBuilder(factory).CreateAsync("6B-SEC", permissions);
}

public sealed class AttendanceMonthlyFinalizationConcurrencyTests
{
    [Fact] public async Task Finalize_vs_finalize() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseRaceAsync(); Assert.Equal(1, await f.Db.PayrollAttendanceSnapshots.CountAsync(x => x.IsCurrent)); }
    [Fact] public async Task Finalize_vs_regularization() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseRaceAsync(); Assert.True(await f.CoherentAsync()); }
    [Fact] public async Task Finalize_vs_OnDuty() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseRaceAsync(); Assert.True(await f.CoherentAsync()); }
    [Fact] public async Task Finalize_vs_leave_change() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseRaceAsync(); Assert.True(await f.CoherentAsync()); }
    [Fact] public async Task Reopen_vs_payroll_calculate() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseAsync(); var result = await f.Processor.ReopenAsync(f.PeriodId, new("controlled correction")); Assert.True(result.Succeeded); }
    [Fact] public async Task Reopen_vs_reopen() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseAsync(); var results = await Task.WhenAll(f.Processor.ReopenAsync(f.PeriodId, new("A")), f.Processor.ReopenAsync(f.PeriodId, new("B"))); Assert.Equal(1, results.Count(x => x.Succeeded)); }
    [Fact] public async Task Refinalize_vs_payroll_calculate() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseAsync(); await f.Processor.ReopenAsync(f.PeriodId, new("correction")); Assert.True((await f.Processor.ProcessAsync(f.PeriodId)).Succeeded); Assert.True((await f.Processor.CloseAsync(f.PeriodId)).Succeeded); Assert.Equal(2, await f.Db.PayrollAttendanceSnapshots.CountAsync()); }
    [Fact] public async Task Duplicate_current_snapshot_race() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseRaceAsync(); Assert.Equal(1, await f.Db.PayrollAttendanceSnapshots.CountAsync(x => x.IsCurrent)); }
}

public sealed class AttendanceMonthlyFinalizationFailureInjectionTests
{
    [Fact] public async Task Summary_generation_failure_does_not_false_finalize() { await using var f = await Phase6BAcceptanceData.ReadyAsync(new ThrowOnSecondSave()); var result = await f.Processor.ProcessAsync(f.PeriodId); Assert.False(result.Succeeded); Assert.NotEqual(AttendancePeriodStatus.Closed, (await f.Db.AttendancePeriods.SingleAsync(x => x.Id == f.PeriodId)).Status); }
    [Fact] public async Task Snapshot_persistence_failure_retry_safe() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); Assert.True((await f.Processor.CloseAsync(f.PeriodId)).Succeeded); Assert.Single(await f.Db.PayrollAttendanceSnapshots.ToListAsync()); }
    [Fact] public async Task Period_finalize_failure_retry_safe() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); Assert.True((await f.Processor.CloseAsync(f.PeriodId)).Succeeded); Assert.Equal(AttendancePeriodStatus.Closed, (await f.Db.AttendancePeriods.SingleAsync(x => x.Id == f.PeriodId)).Status); }
    [Fact] public async Task Reopen_failure_preserves_previous_final_version() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); await f.CloseAsync(); Assert.True((await f.Processor.ReopenAsync(f.PeriodId, new("audit correction"))).Succeeded); Assert.True(await f.Db.PayrollAttendanceSnapshots.AnyAsync(x => x.Version == 1)); }
    [Fact] public async Task Payroll_snapshot_resolution_failure_has_no_partial_payroll_mutation() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); var resolver = new AttendancePayrollSnapshotResolver(f.Db, f.Scope); var missing = await resolver.ResolveAsync(Guid.NewGuid(), new(2026, 9, 1), new(2026, 9, 30)); Assert.False(missing.Succeeded); Assert.Null(missing.Value); }

    private sealed class ThrowOnSecondSave : SaveChangesInterceptor { private int saves; public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData e, InterceptionResult<int> r, CancellationToken ct = default) { if (Interlocked.Increment(ref saves) == 2) throw new InvalidOperationException("injected"); return base.SavingChangesAsync(e, r, ct); } }
}

public sealed class AttendancePayrollIntegrationTests
{
    [Fact] public async Task Payroll_consumes_finalized_snapshot() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(); Assert.Single(await f.Db.PayrollAttendanceSnapshots.Where(x => x.IsCurrent).ToListAsync()); }
    [Fact] public async Task Payroll_rejects_missing_final_attendance() { await using var f = await Phase6BAcceptanceData.ReadyAsync(); var resolver = new AttendancePayrollSnapshotResolver(f.Db, f.Scope); var result = await resolver.ResolveAsync(f.EmployeeId, new(2026, 9, 1), new(2026, 9, 30)); Assert.False(result.Succeeded); }
    [Fact] public async Task Payroll_uses_correct_attendance_version() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(); var snapshot = await f.Db.PayrollAttendanceSnapshots.SingleAsync(x => x.IsCurrent); Assert.Equal(1, snapshot.Version); }
    [Fact] public async Task Refinalized_attendance_does_not_mutate_prior_payroll() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(); await f.Processor.ReopenAsync(f.PeriodId, new("correction")); await f.Processor.ProcessAsync(f.PeriodId); await f.Processor.CloseAsync(f.PeriodId); Assert.Equal(2, await f.Db.PayrollAttendanceSnapshots.CountAsync()); Assert.Equal(1, (await f.Db.PayrollAttendanceSnapshots.OrderBy(x => x.Version).FirstAsync()).Version); }
    [Fact] public async Task Finalized_payroll_protects_attendance_correction() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(); Assert.Equal(AttendancePeriodStatus.Closed, (await f.Db.AttendancePeriods.SingleAsync(x => x.Id == f.PeriodId)).Status); }
    [Fact] public async Task Mid_month_join_does_not_double_prorate() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(joining: new(2026, 9, 11)); var snapshot = await f.Db.PayrollAttendanceSnapshots.SingleAsync(x => x.IsCurrent); Assert.Equal(20, snapshot.EligibleDays); var payroll = await f.CalculatePayrollAsync(); Assert.True(payroll.Succeeded, payroll.Message); var result = await f.Db.PayrollResults.SingleAsync(x => x.IsCurrent); Assert.Equal(20, result.EligibleDays); Assert.Equal(snapshot.Id, result.AttendanceSnapshotId); Assert.Equal(snapshot.Version, result.AttendanceVersion); Assert.Equal(6666.67m, result.GrossEarnings); }
    [Fact] public async Task DateOfLeaving_is_respected() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(leaving: new(2026, 9, 20)); var snapshot = await f.Db.PayrollAttendanceSnapshots.SingleAsync(x => x.IsCurrent); Assert.Equal(20, snapshot.EligibleDays); var payroll = await f.CalculatePayrollAsync(); Assert.True(payroll.Succeeded, payroll.Message); var result = await f.Db.PayrollResults.SingleAsync(x => x.IsCurrent); Assert.Equal(20, result.EligibleDays); Assert.Equal(6666.67m, result.GrossEarnings); }
    [Fact] public async Task LOP_transferred_exactly_once() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(); var snapshot = await f.Db.PayrollAttendanceSnapshots.SingleAsync(x => x.IsCurrent); Assert.Equal(snapshot.LopDays, snapshot.EligibleDays - snapshot.PayableDays); }
}

public sealed class AttendancePayrollEndToEndTests
{
    [Fact] public async Task Attendance_to_payroll_preserves_exact_snapshot_contract() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(); var s = await f.Db.PayrollAttendanceSnapshots.SingleAsync(x => x.IsCurrent); Assert.Equal(s.PayableDays, s.EligibleDays - s.LopDays); Assert.True(s.Version > 0); }
