public sealed class AttendancePayrollCorrectionEndToEndTests
{
    [Fact] public async Task Correction_creates_v2_without_mutating_v1() { await using var f = await Phase6BAcceptanceData.FinalizedAsync(); var firstCalculation = await f.CalculatePayrollAsync(); Assert.True(firstCalculation.Succeeded, firstCalculation.Message); var first = await f.Db.PayrollResults.AsNoTracking().SingleAsync(x => x.IsCurrent); Assert.Equal(1, first.AttendanceVersion); await f.Processor.ReopenAsync(f.PeriodId, new("approved correction")); var day = await f.Db.EmployeeAttendanceDays.SingleAsync(x => x.EmployeeId == f.EmployeeId && x.BusinessDate == new DateOnly(2026, 9, 15)); day.Status = EmployeeAttendanceDayStatus.Absent; day.WorkedMinutes = 0; await f.Db.SaveChangesAsync(); Assert.True((await f.Processor.ProcessAsync(f.PeriodId)).Succeeded); Assert.True((await f.Processor.CloseAsync(f.PeriodId)).Succeeded); var v1 = await f.Db.PayrollAttendanceSnapshots.SingleAsync(x => x.Version == 1); var v2 = await f.Db.PayrollAttendanceSnapshots.SingleAsync(x => x.IsCurrent); Assert.Equal(2, v2.Version); Assert.NotEqual(v1.Id, v2.Id); Assert.Equal(v1.Id, first.AttendanceSnapshotId); var recalculated = await f.CalculatePayrollAsync(recalculate: true); Assert.True(recalculated.Succeeded, recalculated.Message); var current = await f.Db.PayrollResults.SingleAsync(x => x.IsCurrent); Assert.Equal(v2.Id, current.AttendanceSnapshotId); Assert.Equal(2, current.AttendanceVersion); Assert.Equal(first.Id, await f.Db.PayrollResults.Where(x => x.Id == first.Id).Select(x => x.Id).SingleAsync()); Assert.False(await f.Db.PayrollResults.Where(x => x.Id == first.Id).Select(x => x.IsCurrent).SingleAsync()); }
}

public sealed class AttendanceMonthlyFinalizationLargeDataTests
{
    private readonly ITestOutputHelper output;
    public AttendanceMonthlyFinalizationLargeDataTests(ITestOutputHelper output) => this.output = output;
    [Fact] public async Task Ten_thousand_employee_finalization_and_server_paging() { const int employeeCount = 10000; using var database = new SqliteInMemoryDatabase(); var tenantId = Guid.NewGuid(); await using (var catalog = database.CreateCatalogContext()) { catalog.Tenants.Add(new Tenant { Id = tenantId, TenantCode = $"L{tenantId:N}"[..12], TenantName = "6B Large", Host = $"{tenantId:N}.test", ShardKey = tenantId.ToString("N") }); await catalog.SaveChangesAsync(); } await using (var seed = database.CreateContext(new TestTenantContext(tenantId))) { seed.Tenants.Add(new Tenant { Id = tenantId, TenantCode = $"L{tenantId:N}"[..12], TenantName = "6B Large", Host = $"{tenantId:N}.test", ShardKey = tenantId.ToString("N") }); var employees = new List<Employee>(employeeCount); var histories = new List<EmployeeEmploymentHistory>(employeeCount); var days = new List<EmployeeAttendanceDay>(employeeCount * 30); for (var i = 0; i < employeeCount; i++) { var employeeId = Guid.NewGuid(); employees.Add(new Employee { Id = employeeId, TenantId = tenantId, EmployeeCode = $"6B-{i:D5}", FirstName = "Large", LastName = i.ToString(), Email = $"6b-{i:D5}@test.local", DateOfJoining = new DateOnly(2026, 1, 1), Status = EmployeeStatus.Active }); histories.Add(new EmployeeEmploymentHistory { Id = Guid.NewGuid(), TenantId = tenantId, EmployeeId = employeeId, EffectiveFrom = new DateOnly(2026, 1, 1), EmploymentStatus = EmployeeStatus.Active }); for (var day = new DateOnly(2026, 9, 1); day <= new DateOnly(2026, 9, 30); day = day.AddDays(1)) { var absent = i % 20 == 0 && day == new DateOnly(2026, 9, 15); days.Add(new EmployeeAttendanceDay { Id = Guid.NewGuid(), TenantId = tenantId, EmployeeId = employeeId, BusinessDate = day, Status = absent ? EmployeeAttendanceDayStatus.Absent : EmployeeAttendanceDayStatus.Present, ExpectedWorkMinutes = 480, WorkedMinutes = absent ? 0 : 480, ProcessedAtUtc = DateTime.UtcNow }); } } seed.Employees.AddRange(employees); seed.EmployeeEmploymentHistory.AddRange(histories); seed.EmployeeAttendanceDays.AddRange(days); await seed.SaveChangesAsync(); } var scope = new TestTenantContext(tenantId); await using var db = database.CreateContext(scope); var processor = new AttendanceMonthlyProcessor(db, scope); var period = await processor.CreatePeriodAsync(new(2026, 9)); Assert.True(period.Succeeded, period.Message); var processClock = System.Diagnostics.Stopwatch.StartNew(); var processed = await processor.ProcessAsync(period.Value!.Id); Assert.True(processed.Succeeded, processed.Message); var closed = await processor.CloseAsync(period.Value.Id); Assert.True(closed.Succeeded, closed.Message); processClock.Stop(); var pageClock = System.Diagnostics.Stopwatch.StartNew(); var page = await processor.GetSummariesAsync(period.Value.Id, new() { Page = 1, PageSize = 100 }); pageClock.Stop(); var snapshotCount = await db.PayrollAttendanceSnapshots.CountAsync(x => x.AttendancePeriodId == period.Value.Id); var resolverClock = System.Diagnostics.Stopwatch.StartNew(); var resolved = await new AttendancePayrollSnapshotResolver(db, scope).ResolveAsync(await db.Employees.Select(x => x.Id).FirstAsync(), new DateOnly(2026, 9, 1), new DateOnly(2026, 9, 30)); resolverClock.Stop(); Assert.True(page.Succeeded, page.Message); Assert.Equal(employeeCount, await db.EmployeeAttendanceMonthlySummaries.CountAsync(x => x.AttendancePeriodId == period.Value.Id)); Assert.Equal(employeeCount, snapshotCount); Assert.Equal(employeeCount, await db.PayrollAttendanceSnapshots.CountAsync(x => x.AttendancePeriodId == period.Value.Id && x.IsCurrent)); Assert.Equal(100, page.Value!.Items.Count); Assert.Equal(employeeCount, page.Value.TotalCount); Assert.True(resolved.Succeeded, resolved.Message); output.WriteLine($"Employees={employeeCount}; Finalized={employeeCount}; Blocked=0; Snapshots={snapshotCount}; PageSize=100; FinalizationDuration={processClock.Elapsed}; FirstPageDuration={pageClock.Elapsed}; PayrollSnapshotResolutionDuration={resolverClock.Elapsed}; DuplicateCurrentSnapshots={await db.PayrollAttendanceSnapshots.CountAsync(x => x.AttendancePeriodId == period.Value.Id && x.IsCurrent) - snapshotCount}"); }
}

internal sealed class Phase6BAcceptanceData : IAsyncDisposable
{
    private readonly SqliteInMemoryDatabase database;
    public readonly Guid TenantId; public readonly Guid EmployeeId; public readonly TestTenantContext Scope; public readonly HRMS.Infrastructure.Persistence.HrmsDbContext Db; public readonly AttendanceMonthlyProcessor Processor; public Guid PeriodId { get; private set; }
    private Phase6BAcceptanceData(SqliteInMemoryDatabase database, Guid tenantId, Guid employeeId, TestTenantContext scope, HRMS.Infrastructure.Persistence.HrmsDbContext db, AttendanceMonthlyProcessor processor) { this.database = database; TenantId = tenantId; EmployeeId = employeeId; Scope = scope; Db = db; Processor = processor; }
    public static async Task<Phase6BAcceptanceData> ReadyAsync(IInterceptor? interceptor = null, DateOnly? joining = null, DateOnly? leaving = null) { var db = new SqliteInMemoryDatabase(); var tenant = Guid.NewGuid(); var employee = Guid.NewGuid(); await SeedTenant(db, tenant); var scope = new TestTenantContext(tenant); var interceptors = interceptor is null ? Array.Empty<IInterceptor>() : new[] { interceptor }; var context = db.CreateContext(scope, interceptors); var data = new Phase6BAcceptanceData(db, tenant, employee, scope, context, new AttendanceMonthlyProcessor(context, scope)); await SeedTenantData(db, tenant, employee, joining ?? new(2026, 1, 1), leaving); var period = await data.Processor.CreatePeriodAsync(new(2026, 9)); data.PeriodId = period.Value!.Id; await data.Processor.ProcessAsync(data.PeriodId); return data; }
    public static Task<Phase6BAcceptanceData> FinalizedAsync(DateOnly? joining = null, DateOnly? leaving = null) => FinalizedCore(joining, leaving);
    private static async Task<Phase6BAcceptanceData> FinalizedCore(DateOnly? joining, DateOnly? leaving) { var d = await ReadyAsync(null, joining, leaving); await d.CloseAsync(); return d; }
    public Guid PayrollRunId { get; private set; }
    public async Task CloseAsync() => _ = await Processor.CloseAsync(PeriodId);
    public async Task<Result<PayrollCalculationSummaryDto>> CalculatePayrollAsync(bool recalculate = false)
    {
        if (PayrollRunId == Guid.Empty)
        {
            var structureId = Guid.NewGuid(); var versionId = Guid.NewGuid(); var componentId = Guid.NewGuid(); var assignmentId = Guid.NewGuid(); var periodId = Guid.NewGuid(); var runId = Guid.NewGuid();
            Db.SalaryComponents.Add(new SalaryComponent { Id = componentId, TenantId = TenantId, Code = "6B-BASIC", Name = "6B Basic", ComponentType = SalaryComponentType.Earning, CalculationType = SalaryCalculationType.FixedAmount, EffectiveFrom = new DateOnly(2026, 1, 1), IsActive = true, AffectsGross = true, AffectsNetPay = true });
            Db.SalaryStructures.Add(new SalaryStructure { Id = structureId, TenantId = TenantId, Code = "6B-STRUCT", Name = "6B Structure", IsActive = true });
            var version = new SalaryStructureVersion { Id = versionId, TenantId = TenantId, SalaryStructureId = structureId, EffectiveFrom = new DateOnly(2026, 1, 1), IsActive = true };
            version.Components.Add(new SalaryStructureComponent { Id = Guid.NewGuid(), TenantId = TenantId, SalaryStructureVersionId = versionId, SalaryComponentId = componentId, Sequence = 1, CalculationType = SalaryStructureCalculationType.FixedAmount, Value = 10000m, IsProratable = true, EffectiveFrom = new DateOnly(2026, 1, 1), IsActive = true });
            Db.SalaryStructureVersions.Add(version);
            var employee = await Db.Employees.SingleAsync(x => x.Id == EmployeeId);
            Db.EmployeeSalaryAssignments.Add(new EmployeeSalaryAssignment { Id = assignmentId, TenantId = TenantId, EmployeeId = EmployeeId, SalaryStructureId = structureId, SalaryStructureVersionId = versionId, EffectiveFrom = employee.DateOfJoining, EffectiveTo = employee.DateOfLeaving, MonthlyCtc = 10000m, CurrencyCode = "INR", Status = EmployeeSalaryAssignmentStatus.Active });
            var payrollPeriod = new PayrollPeriod { Id = periodId, TenantId = TenantId, Code = "6B-SEP", Name = "6B September", PeriodType = PayrollPeriodType.Monthly, StartDate = new DateOnly(2026, 9, 1), EndDate = new DateOnly(2026, 9, 30), PayDate = new DateOnly(2026, 10, 5), FiscalYear = 2026, PeriodNumber = 9, Status = PayrollPeriodStatus.Open, IsActive = true };
            Db.PayrollPeriods.Add(payrollPeriod); Db.PayrollRuns.Add(new PayrollRun { Id = runId, TenantId = TenantId, PayrollPeriodId = periodId, RunNumber = "6B-RUN", Status = PayrollRunStatus.Prepared, EmployeeCount = 1 });
            Db.PayrollRunEmployees.Add(new PayrollRunEmployee { Id = Guid.NewGuid(), TenantId = TenantId, PayrollRunId = runId, EmployeeId = EmployeeId, EmployeeSalaryAssignmentId = assignmentId, SalaryStructureId = structureId, SalaryStructureVersionId = versionId, EmploymentSnapshotDate = payrollPeriod.EndDate, IsEligible = true, Status = PayrollRunEmployeeStatus.Eligible });
            await Db.SaveChangesAsync(); PayrollRunId = runId;
        }
        var resolver = new AttendancePayrollSnapshotResolver(Db, Scope);
        return await new PayrollCalculationEngine(Db, Scope, TimeProvider.System, attendance: resolver).CalculateAsync(PayrollRunId, recalculate);
    }
    public async Task CloseRaceAsync() { await using var a = database.CreateIsolatedContext(new TestTenantContext(TenantId)); await using var b = database.CreateIsolatedContext(new TestTenantContext(TenantId)); await Task.WhenAll(new AttendanceMonthlyProcessor(a, new TestTenantContext(TenantId)).CloseAsync(PeriodId), new AttendanceMonthlyProcessor(b, new TestTenantContext(TenantId)).CloseAsync(PeriodId)); }
    public async Task<bool> CoherentAsync() => await Db.PayrollAttendanceSnapshots.CountAsync(x => x.IsCurrent) <= 1;
    public ValueTask DisposeAsync() { Db.Dispose(); database.Dispose(); return ValueTask.CompletedTask; }
    private static async Task SeedTenant(SqliteInMemoryDatabase db, Guid tenant) { await using var catalog = db.CreateCatalogContext(); await catalog.Tenants.AddAsync(new Tenant { Id = tenant, TenantCode = $"P{tenant:N}"[..12], Host = $"{tenant:N}.localhost", ShardKey = tenant.ToString("N") }); await catalog.SaveChangesAsync(); await using var shard = db.CreateContext(new TestTenantContext(tenant)); shard.Tenants.Add(new Tenant { Id = tenant, TenantCode = $"P{tenant:N}"[..12], Host = $"{tenant:N}.localhost", ShardKey = tenant.ToString("N") }); await shard.SaveChangesAsync(); }
    private static async Task SeedTenantData(SqliteInMemoryDatabase db, Guid tenant, Guid employee, DateOnly joining, DateOnly? leaving) { await using var seed = db.CreateContext(new TestTenantContext(tenant)); seed.Employees.Add(new Employee { Id = employee, TenantId = tenant, EmployeeCode = "6B-001", FirstName = "Phase", LastName = "SixB", Email = $"{employee:N}@test.local", DateOfJoining = joining, DateOfLeaving = leaving }); seed.EmployeeEmploymentHistory.Add(new EmployeeEmploymentHistory { Id = Guid.NewGuid(), TenantId = tenant, EmployeeId = employee, EffectiveFrom = joining, EffectiveTo = leaving, EmploymentStatus = EmployeeStatus.Active }); for (var day = new DateOnly(2026, 9, 1); day <= new DateOnly(2026, 9, 30); day = day.AddDays(1)) if (day >= joining && (leaving is null || day <= leaving.Value)) seed.EmployeeAttendanceDays.Add(new EmployeeAttendanceDay { Id = Guid.NewGuid(), TenantId = tenant, EmployeeId = employee, BusinessDate = day, Status = EmployeeAttendanceDayStatus.Present, ExpectedWorkMinutes = 480, WorkedMinutes = 480, ProcessedAtUtc = DateTime.UtcNow }); await seed.SaveChangesAsync(); }
}
